  if (!pluginState.initialized) return;

  await Promise.all([
    pluginState.nervousSystemBridge?.destroy(),
    pluginState.attentionBridge?.destroy(),
  ]);

  pluginState = {
    initialized: false,
    nervousSystemBridge: null,
    attentionBridge: null,
  };
}

